const recipeRegions={silog:['Philippines','Singapore'],tinola:['Philippines'],adobo:['Philippines'],monggo:['Philippines'],tofu:['Philippines','Singapore'],sardine:['Philippines'],chicken:['Australia','Philippines','Singapore'],tuna:['Australia','Philippines','Singapore'],oats:['Australia','Singapore'],overnight:['Australia','Singapore']};
export const regionNames=Object.keys(regions);
export function countryForCity(city){for(const [country,region]of Object.entries(regions))if(city in region.cities)return {id:city,country};return {id:'perth',country:'Australia'};}
export function regionFor(cityInfo){return regions[cityInfo?.country]||regions.Australia;}
export function localCurrency(cityInfo){return regionFor(cityInfo).currency;}
export function defaultBudget(cityInfo){return regionFor(cityInfo).budget;}
export function shops(cityInfo){return Object.keys(regionFor(cityInfo).shops);}
export function reviewed(cityInfo){return regionFor(cityInfo).reviewed;}
export function applyRegionalCatalog(ingredients,recipes,state,cityInfo){const region=regionFor(cityInfo),shop=state.region?.shop||Object.keys(region.shops)[0],multiplier=(region.cities[cityInfo?.id]||1)*(region.shops[shop]||1);for(const id of Object.keys(region.food))if(!ingredients[id]&&supplementalIngredients[id])ingredients[id]=structuredClone(supplementalIngredients[id]);for(const id of new Set(recipes.filter(recipe=>recipe.id.startsWith('custom-')).flatMap(recipe=>Object.keys(recipe.items))))if(!ingredients[id]&&supplementalIngredients[id])ingredients[id]=structuredClone(supplementalIngredients[id]);for(const [id,ingredient]of Object.entries(ingredients)){if(id.startsWith('custom-'))continue;const local=region.food[id];if(local)Object.assign(ingredient,{name:local[0],pack:local[1],price:+(local[2]*multiplier).toFixed(2),packageLabel:local[3],priceReviewed:region.reviewed,localPrice:true});else if(cityInfo?.country==='Australia'&&!supplementalIngredients[id])Object.assign(ingredient,{packageLabel:(ingredient.pack||1000)+' g',priceReviewed:region.reviewed,localPrice:true});else Object.assign(ingredient,{price:0,packageLabel:'Add price',priceReviewed:region.reviewed,localPrice:false});}for(const recipe of recipes)recipe.regions=recipe.id.startsWith('custom-')?regionNames:recipeRegions[recipe.id]||regionNames.filter(country=>Object.keys(recipe.items).every(id=>regions[country].food[id]));}
export function isLocalRecipe(recipe,cityInfo){return recipe.id.startsWith('custom-')||!recipe.regions||recipe.regions.includes(cityInfo?.country);}
export function conversionRate(rates,from,to){if(from===to)return 1;const a=Number(rates?.[from]),b=Number(rates?.[to]);return a>0&&b>0?b/a:1;}
